# Shared web layer for all labs. Learners do not edit this file.
# Each lab mounts its own code at /app; this file calls /app/cache.py.
import os

import asyncpg
import redis.asyncio as redis
from fastapi import FastAPI, HTTPException

import cache

app = FastAPI()


@app.on_event("startup")
async def startup():
    app.state.db = await asyncpg.create_pool(os.environ["DATABASE_URL"], min_size=2, max_size=20)
    app.state.redis = redis.from_url(os.environ["REDIS_URL"], decode_responses=True)


@app.on_event("shutdown")
async def shutdown():
    await app.state.db.close()
    await app.state.redis.aclose()


@app.get("/products/{product_id}/summary")
async def product_summary(product_id: int):
    summary = await cache.get_summary(product_id, app.state.redis, app.state.db)
    if summary is None:
        raise HTTPException(404)
    return summary


@app.get("/health")
async def health():
    return {"ok": True}
